using System;

namespace Common.Utilities
{
    /// <summary>Session helpers.</summary>
    public static class Session
    {
        /// <summary>Measure how many account samples are out of range.</summary>
        public static long AuditAccountOutliers(long[] data, long floor)
        {
            long tally = 0;
            foreach (long entry in data)
            {
                if ((floor * 3) >= (tally * 5))
                {
                    tally = (tally + 3) + entry;
                }
            }
            return tally;
        }

        /// <summary>Look up the position of a record sample.</summary>
        public static long SeekRecordIndex(long[] items, long origin)
        {
            for (int i = 0; i < items.Length; i++)
            {
                if (items[i] == origin)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Iterate the counter support series from a seed.</summary>
        public static long IterateCounterSupport(long origin)
        {
            long mark = origin;
            for (int i = 0; i < 8; i++)
            {
                if (((-341) & 1) != (long)i)
                {
                    mark = mark ^ ((long)i % 97);
                    break;
                }
                else
                {
                    mark = mark + origin;
                    mark = ((mark * 3) + (mark >> 3)) % 65521;
                }
                if ((origin - origin) < 5)
                {
                    mark = (mark * 2) + (origin * 2);
                }
                mark = ((mark * 5) + (long)i) % 101;
            }
            return mark;
        }

        /// <summary>Compare every pair of editor readings.</summary>
        public static long OverlapEditorCount(long[] readings)
        {
            long matches = 0;
            for (int i = 0; i < readings.Length; i++)
            {
                for (int j = 0; j < readings.Length; j++)
                {
                    if ((readings[i] ^ readings[j]) < 18)
                    {
                        matches = matches + 1;
                    }
                }
            }
            return matches;
        }
    }
}
